\set ON_ERROR_STOP on
\o /dev/null
begin;
select set_config('app.audit_reason','Fixtures isoladas de segurança e comércio',true);
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'ASSERTION FAILED: %',message;end if;end $$;
grant execute on function pg_temp.assert(boolean,text) to anon,authenticated,service_role;
insert into auth.users(id) values('a0000000-0000-0000-0000-000000000001'),('a0000000-0000-0000-0000-000000000002'),('a0000000-0000-0000-0000-000000000003'),('a0000000-0000-0000-0000-000000000004');
update public.profiles set role='admin',active=true where id='a0000000-0000-0000-0000-000000000001';
update public.profiles set active=true where id in ('a0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000003');
update public.profiles set role='kitchen',sector='grill',active=true where id='a0000000-0000-0000-0000-000000000004';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","session_id":"admin-advanced"}',true);
select set_config('test.device2',(public.register_terminal('Balcão seguro','Cadastro de dispositivo autorizado')->>'token'),true);
select public.set_staff_pin('a0000000-0000-0000-0000-000000000002','1212');
select public.set_staff_pin('a0000000-0000-0000-0000-000000000003','3434');
select public.set_staff_pin('a0000000-0000-0000-0000-000000000004','5656');
select set_config('test.admin_shift',public.open_shift(10000)::text,true);
select set_config('test.ingredient',public.save_ingredient(null,'Porção de cebola teste','un',5,100,'Cadastro de insumo para conferência')::text,true);
select public.adjust_stock(current_setting('test.ingredient')::uuid,20,'Estoque inicial conferido','b0000000-0000-0000-0000-000000000001');
select public.adjust_stock(current_setting('test.ingredient')::uuid,20,'Estoque inicial conferido','b0000000-0000-0000-0000-000000000001');
select pg_temp.assert((select stock from public.ingredients where id=current_setting('test.ingredient')::uuid)=20,'stock adjustment retry does not duplicate');
select pg_temp.assert(exists(select 1 from public.audit_log where action='inventory.changed' and entity_key=current_setting('test.ingredient') and quantity_delta=20 and actor_id=auth.uid()),'stock changes automatically audited with actor and quantity');
do $$begin
 begin perform public.adjust_stock(current_setting('test.ingredient')::uuid,1,'','b0000000-0000-0000-0000-000000000002');raise exception 'missing stock reason accepted';exception when others then if sqlerrm<>'justification_required' then raise;end if;end;
 begin update public.audit_log set justification='fraude';raise exception 'admin edited audit';exception when insufficient_privilege then null;end;
 begin delete from public.audit_log;raise exception 'admin deleted audit';exception when insufficient_privilege then null;end;
 begin truncate public.audit_log;raise exception 'admin truncated audit';exception when insufficient_privilege then null;end;
end $$;
select public.save_recipe('simples',jsonb_build_array(jsonb_build_object('ingredient_id',current_setting('test.ingredient'),'quantity',1)),jsonb_build_array(jsonb_build_object('modifier','Sem cebola','ingredient_id',current_setting('test.ingredient'),'quantity_delta',-1)),'Regra de consumo de teste por modificador');
select set_config('test.link',(public.create_order_link('Delivery seguro','delivery',30,'Abertura do canal de delivery')->>'token'),true);
set local role anon;
select pg_temp.assert(jsonb_array_length(public.checkout_menu(current_setting('test.link'))->'products')=47,'anonymous menu limited to public product fields');
select pg_temp.assert(not ((public.checkout_menu(current_setting('test.link'))->'products'->0)?'unit_cost_cents'),'public menu has no costs');
select set_config('test.public_order',(public.checkout_order(current_setting('test.link'),'b0000000-0000-0000-0000-000000000003',repeat('a',64),'{"name":"Cliente privado","phone":"5581999999999","address":"Endereço privado de entrega","whatsapp_consent":false}','[{"product_id":"simples","quantity":1,"price_cents":1,"modifiers":["Sem cebola"]}]')->>'id'),true);
select pg_temp.assert((public.checkout_status(repeat('a',64))->>'total_cents')::int=700,'public checkout uses database price');
select pg_temp.assert(not(public.checkout_status(repeat('a',64))?'phone') and not(public.checkout_status(repeat('a',64))?'address'),'tracking never exposes private contacts');
select pg_temp.assert((public.checkout_order(current_setting('test.link'),'b0000000-0000-0000-0000-000000000003',repeat('a',64),'{"name":"Cliente privado","phone":"5581999999999","address":"Endereço privado de entrega","whatsapp_consent":false}','[{"product_id":"simples","quantity":1,"price_cents":1,"modifiers":["Sem cebola"]}]')->>'id')=current_setting('test.public_order'),'public retry is idempotent');
do $$begin
 begin perform 1 from public.customer_contacts;raise exception 'anonymous contact export allowed';exception when insufficient_privilege then null;end;
 begin perform public.checkout_status(repeat('0',64));raise exception 'unknown tracking accepted';exception when insufficient_privilege then null;end;
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","session_id":"cash-one"}',true);
select public.unlock_terminal('0000',current_setting('test.device2')) from generate_series(1,2);
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000003","session_id":"cash-two"}',true);
select public.unlock_terminal('0000',current_setting('test.device2')) from generate_series(1,2);
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000004","session_id":"kitchen-new-session"}',true);
select public.unlock_terminal('0000',current_setting('test.device2'));
select pg_temp.assert((public.unlock_terminal('5656',current_setting('test.device2'))->>'ok')::boolean=false,'terminal lockout survives account and session changes');
select pg_temp.assert((select count(*) from public.customer_contacts)=0,'kitchen cannot export delivery base');
reset role;
select pg_temp.assert(exists(select 1 from app_private.terminal_attempts where locked_until=now()+interval '3 minutes'),'lockout lasts exactly three minutes');
select pg_temp.assert(exists(select 1 from public.audit_log where action='terminal.pin_lockout'),'terminal lockout is audited');
update app_private.terminal_attempts set locked_until=now()-interval '1 second';
set local role authenticated;
select pg_temp.assert((public.unlock_terminal('5656',current_setting('test.device2'))->>'ok')::boolean,'terminal unlocks after lockout expiry');
select pg_temp.assert((public.unlock_terminal('5656',repeat('0',64))->>'ok')::boolean=false,'unregistered terminal cannot bypass rate limit');
reset role;
update app_private.terminal_leases set expires_at=now()-interval '1 second';
set local role authenticated;
select pg_temp.assert((public.heartbeat_terminal()->>'ok')::boolean=false,'heartbeat cannot revive expired inactivity lease');
select pg_temp.assert((select count(*) from public.kitchen_tickets)=0,'expired KDS lease has no ticket access');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","session_id":"cash-one"}',true);
select public.unlock_terminal('1212',current_setting('test.device2'));
select set_config('test.cash_shift',public.open_shift(1000)::text,true);
select pg_temp.assert((select count(*) from public.customer_contacts)=0,'cashier has no unassigned contact access');
select public.claim_external_order(current_setting('test.public_order')::uuid);
select pg_temp.assert((select count(*) from public.customer_contacts)=0,'private delivery contact not exposed before payment');
select public.cash_movement(current_setting('test.cash_shift')::uuid,'withdrawal',200,'Sangria conferida pelo operador','b0000000-0000-0000-0000-000000000004');
select public.cash_movement(current_setting('test.cash_shift')::uuid,'withdrawal',200,'Sangria conferida pelo operador','b0000000-0000-0000-0000-000000000004');
select pg_temp.assert((public.cash_summary(current_setting('test.cash_shift')::uuid)->>'expected_cents')::int=800,'withdrawal is idempotent');
do $$begin
 begin perform public.cash_movement(current_setting('test.cash_shift')::uuid,'withdrawal',900,'Retirada maior que saldo','b0000000-0000-0000-0000-000000000005');raise exception 'overdraw allowed';exception when others then if sqlerrm<>'insufficient_cash' then raise;end if;end;
 begin perform public.apply_discount(current_setting('test.public_order')::uuid,100,'Desconto sem autorização');raise exception 'cashier discount allowed';exception when insufficient_privilege then null;end;
 begin perform public.admin_metrics(now()-interval '1 day',now()+interval '1 day');raise exception 'cashier analytics allowed';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","session_id":"admin-advanced"}',true);
select public.apply_discount(current_setting('test.public_order')::uuid,100,'Cortesia autorizada de teste');
select pg_temp.assert((select total_cents from public.orders where id=current_setting('test.public_order')::uuid)=600,'authorized discount affects server total');
select pg_temp.assert(exists(select 1 from public.audit_log where action='order.discounted' and amount_cents=-100 and justification='Cortesia autorizada de teste'),'discount audited automatically');
select set_config('test.attempt2',(public.begin_payment(current_setting('test.public_order')::uuid,'pix','b0000000-0000-0000-0000-000000000006')).id::text,true);
set local role service_role;
select public.record_pix_artifact(current_setting('test.attempt2')::uuid,'000201FIXTURE_MANUAL_PIX_TEST_ONLY',null);
set local role authenticated;
select public.confirm_manual_pix(current_setting('test.attempt2')::uuid,'REFBANCO0001','Crédito confirmado no extrato de teste');
select public.confirm_manual_pix(current_setting('test.attempt2')::uuid,'refbanco0001','Crédito confirmado no extrato de teste');
select pg_temp.assert((select count(*) from public.kitchen_tickets where order_id=current_setting('test.public_order')::uuid)=1,'manual PIX releases one ticket');
select pg_temp.assert((select stock from public.ingredients where id=current_setting('test.ingredient')::uuid)=20,'modifier excludes configured recipe consumption');
select pg_temp.assert(not exists(select 1 from public.kitchen_tickets where customer like '%Cliente privado%'),'KDS alias does not expose customer identity');
select set_config('test.another_order',(public.checkout_order(current_setting('test.link'),'b0000000-0000-0000-0000-000000000008',repeat('b',64),'{"name":"Outro cliente","phone":"5581888888888","address":"Outro endereço de entrega"}','[{"product_id":"agua","quantity":1}]')->>'id'),true);
select set_config('test.another_attempt',(public.begin_payment(current_setting('test.another_order')::uuid,'pix','b0000000-0000-0000-0000-000000000009')).id::text,true);
set local role service_role;
select public.record_pix_artifact(current_setting('test.another_attempt')::uuid,'000201FIXTURE_MANUAL_PIX_SECOND_TEST_ONLY',null);
set local role authenticated;
do $$begin
 begin perform public.confirm_manual_pix(current_setting('test.another_attempt')::uuid,'refbanco0001','Tentativa duplicada no outro pedido');raise exception 'bank credit reused';exception when unique_violation then null;end;
end $$;
select pg_temp.assert((select status from public.orders where id=current_setting('test.another_order')::uuid)='pending_payment','one bank reference cannot pay two orders, regardless of case');
select pg_temp.assert((public.admin_metrics(now()-interval '1 day',now()+interval '1 day')->>'revenue_cents')::int=600,'analytics reflects confirmed discounted sale');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","session_id":"cash-one"}',true);
select pg_temp.assert((select phone from public.customer_contacts where order_id=current_setting('test.public_order')::uuid)='5581999999999','assigned active cashier can fulfill paid delivery');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000003","session_id":"cash-two"}',true);
select public.unlock_terminal('3434',current_setting('test.device2'));
select pg_temp.assert((select count(*) from public.customer_contacts)=0,'other cashier cannot export contact');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000004","session_id":"kitchen-new-session"}',true);
select public.unlock_terminal('5656',current_setting('test.device2'));
select pg_temp.assert((select count(*) from public.customer_contacts)=0,'kitchen still has no private contact after payment');
select public.update_ticket((select id from public.kitchen_tickets where order_id=current_setting('test.public_order')::uuid),'preparing');
select public.update_ticket((select id from public.kitchen_tickets where order_id=current_setting('test.public_order')::uuid),'ready');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","session_id":"cash-one"}',true);
select public.dispatch_order(current_setting('test.public_order')::uuid);
select public.deliver_order(current_setting('test.public_order')::uuid);
select pg_temp.assert((select count(*) from public.customer_contacts)=0,'contacts disappear from cashier after fulfillment');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","session_id":"admin-advanced"}',true);
select set_config('test.refund2',(public.request_refund(current_setting('test.public_order')::uuid,'b0000000-0000-0000-0000-000000000007','Devolução solicitada pelo cliente de teste')).id::text,true);
select public.confirm_manual_pix_refund(current_setting('test.refund2')::uuid,'DEVOLUCAO0001');
select public.confirm_manual_pix_refund(current_setting('test.refund2')::uuid,'DEVOLUCAO0001');
select pg_temp.assert((select status from public.payment_attempts where id=current_setting('test.attempt2')::uuid)='refunded','refund completion changes payment state');
select pg_temp.assert(exists(select 1 from public.audit_log where action='payment.refunded' and amount_cents=-600),'refund recorded automatically');
select public.anonymize_customer(current_setting('test.public_order')::uuid,'Solicitação de privacidade concluída');
select pg_temp.assert((select phone||address||email from public.customer_contacts where order_id=current_setting('test.public_order')::uuid)='','anonymization removes private delivery data');
select public.void_pending_manual_pix(current_setting('test.another_order')::uuid,'Cliente desistiu, crédito não consta no extrato');
select public.confirm_manual_pix(current_setting('test.another_attempt')::uuid,'CREDITOTARDIO0001','Crédito tardio conferido após encerramento');
select pg_temp.assert((select status from public.orders where id=current_setting('test.another_order')::uuid)='cancelled','late credit does not reopen cancelled food order');
select pg_temp.assert(not exists(select 1 from public.kitchen_tickets where order_id=current_setting('test.another_order')::uuid),'late credit never reaches KDS');
select pg_temp.assert(exists(select 1 from public.audit_log where action='payment.pix_late_received'),'late credit is audited');
select pg_temp.assert((public.admin_metrics(now()-interval '1 day',now()+interval '1 day')->>'cancelled_credit_cents')::int=200,'unrefunded late credit is visible to management');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","session_id":"cash-one"}',true);
select public.close_shift(current_setting('test.cash_shift')::uuid,800,'Fechamento conferido após sangria');
select public.cash_movement(current_setting('test.cash_shift')::uuid,'withdrawal',200,'Sangria conferida pelo operador','b0000000-0000-0000-0000-000000000004');
select pg_temp.assert((public.cash_summary(current_setting('test.cash_shift')::uuid)->>'expected_cents')::int=800,'withdrawal retry after close does not debit twice');
set local role service_role;
do $$begin
 begin delete from public.audit_log;raise exception 'service deleted audit';exception when insufficient_privilege then null;end;
end $$;
reset role;
do $$begin
 begin update public.audit_log set justification='Alteração privilegiada';raise exception 'owner DML bypassed immutable trigger';exception when insufficient_privilege then null;end;
 begin truncate public.audit_log;raise exception 'owner truncate bypassed immutable trigger';exception when insufficient_privilege then null;end;
end $$;
rollback;
\o
\echo 'ADVANCED OK: immutable audit, reasons/amounts/quantities, terminal 5-attempt/180s lockout, inactivity leases, RLS delivery privacy, QR checkout, discounts, withdrawals, manual PIX/refund and anonymization.'
